<?php require __DIR__.'/core/bootstrap.php';if(user())go('cliente/index.php');$error='';if(is_post()){verify_csrf();try{if(!rate_limit('register',5,3600))throw new InvalidArgumentException('Muitas tentativas. Tente novamente mais tarde.');$name=input('name',120);$email=strtolower(input('email',190));$pass=input('password',200);if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<12||$pass!==input('confirm',200))throw new InvalidArgumentException('Informe nome, e-mail válido e senhas iguais com pelo menos 12 caracteres.');if(one('SELECT id FROM users WHERE email=?',[$email]))throw new InvalidArgumentException('Não foi possível cadastrar este e-mail. Se já tem conta, faça login.');run('INSERT INTO users (name,email,password_hash,role,active,created_at) VALUES (?,?,?,\'client\',1,?)',[$name,$email,password_hash($pass,PASSWORD_DEFAULT),date('Y-m-d H:i:s')]);session_regenerate_id(true);$_SESSION['uid']=(int)db()->lastInsertId();$_SESSION['csrf']=bin2hex(random_bytes(32));flash('Conta criada com sucesso.');go('cliente/index.php');}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}}$pageTitle='Criar conta — S7VEN';require ROOT.'/includes/header.php';?><main class="auth-box"><h1>Crie sua conta.</h1><p>Acompanhe seu projeto em um só lugar.</p><?php if($error):?><div class="errors"><?=e($error)?></div><?php endif;?><form method="post"><?php csrf();?><label class="field">Nome<input name="name" required maxlength="120" autocomplete="name"></label><label class="field">E-mail<input name="email" type="email" required maxlength="190" autocomplete="email"></label><label class="field">Senha (mínimo 12 caracteres)<input type="password" name="password" required minlength="12" maxlength="200" autocomplete="new-password"></label><label class="field">Confirme a senha<input type="password" name="confirm" required minlength="12" maxlength="200" autocomplete="new-password"></label><p>Usamos os dados para gerir sua conta e atendimento. <a href="<?=e(url('privacidade.php'))?>">Consulte a privacidade</a>.</p><button class="primary wide">Criar conta ↗</button></form><p><a href="<?=e(url('login.php'))?>">Já tenho uma conta</a></p></main><?php require ROOT.'/includes/footer.php';?>
